import React from 'react';
// Import the image from its path in the img folder
import NaturalBackgroundImage from 'scr/img/Natural.png';

const styles = {
  section: {
    padding: '64px 24px', // Increased padding for better spacing
    position: 'relative', // Necessary for the overlay to work
    textAlign: 'center',
    color: 'white', // Set the default text color to white for readability
    // Use the imported image as the background
    backgroundImage: `url(${NaturalBackgroundImage})`,
    backgroundSize: 'cover', // Ensures the image covers the section
    backgroundPosition: 'center', // Centers the image
    backgroundAttachment: 'fixed', // Creates a parallax-like effect
  },
  overlay: {
    // This div sits on top of the image but behind the text
    position: 'absolute',
    top: 0,
    left: 0,
    right: 0,
    bottom: 0,
    backgroundColor: 'rgba(0, 0, 0, 0.55)', // A black overlay with 55% opacity
    zIndex: 1, // Places the overlay above the background image
  },
  container: {
    maxWidth: '1200px',
    margin: '0 auto',
    position: 'relative', // Ensures the content is positioned correctly
    zIndex: 2, // Places the content on top of the overlay
    display: 'flex',
    flexDirection: 'column',
    alignItems: 'center',
  },
  h2: {
    fontSize: '2.5rem',
    fontWeight: 'normal', // A lighter weight for the top heading
    color: '#ffffff',
    marginBottom: '8px',
  },
  h3: {
    fontSize: '2.5rem',
    fontWeight: 'bold',
    color: '#a7ffeb', // A lighter, vibrant teal that pops on a dark background
    marginBottom: '24px',
  },
  textContent: {
    color: '#f0f0f0', // A slightly off-white for the body text
    fontSize: '1.2rem',
    lineHeight: '1.7',
    maxWidth: '800px',
  },
  button: {
    backgroundColor: '#00796b', // Use the brand's teal color
    color: '#ffffff',
    fontWeight: 'bold',
    padding: '12px 24px',
    borderRadius: '8px',
    border: 'none', // Remove the border for a cleaner look
    cursor: 'pointer',
    marginTop: '32px', // More space above the button
    fontSize: '1rem',
    transition: 'background-color 0.3s ease-in-out', // Smooth transition for hover
  },
};

const Hero = () => {
  return (
    <section id="about" style={styles.section}>
      {/* Add the overlay div here */}
      <div style={styles.overlay}></div>

      {/* The container holds all the content */}
      <div style={styles.container}>
        <h2 style={styles.h2}>Getting to Know</h2>
        <h3 style={styles.h3}>"Coimbatore Dietitian Pradeepa"</h3>
        <div style={styles.textContent}>
          <p>
            <strong>Pradeepa Saravanan</strong> is a Coimbatore-based consultant Dietitian/Nutritionist...
          </p>
          <p style={{ marginTop: '16px' }}>
            She says, "Diet is the cornerstone of health and vitality..."
          </p>
          <button
            style={styles.button}
            // Add a simple hover effect inline
            onMouseOver={(e) => e.currentTarget.style.backgroundColor = '#004d40'}
            onMouseOut={(e) => e.currentTarget.style.backgroundColor = '#00796b'}
          >
            How do you feel being a dietitian?
          </button>
        </div>
      </div>
    </section>
  );
};

export default Hero;
